import{_ as s,a0 as a,w as p,s as i,ao as l,I as r,x as n,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Turn Off Shutdown ／ Restart Confirmation In Ubuntu","title":"每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Turn Off Shutdown ／ Restart Confirmation In Ubuntu.md","filePath":"[post].md"}'),d={name:"201402/Daily Ubuntu Tips – Turn Off Shutdown ／ Restart Confirmation In Ubuntu.md"};function b(f,t,m,T,g,w){const u=a("Link");return p(),i("div",null,[t[11]||(t[11]=l(`<h1 id="每日-ubuntu-小技巧——关闭-ubuntu-中的关机-重启确认" tabindex="-1">每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认 <a class="header-anchor" href="#每日-ubuntu-小技巧——关闭-ubuntu-中的关机-重启确认" aria-label="Permalink to “每日 Ubuntu 小技巧——关闭 Ubuntu 中的关机/重启确认”">​</a></h1><p>对于 Ubuntu 新手来说，有很多新东西要学，但是网上很多教程不是针对新手的。</p><p>在这里，我们不走寻常路。不能说全部的教程都是为初学者准备，但至少大部分是。</p><p>这篇文章也是一篇新手教程，并且展示如何在每次执行关机、重启、注销时禁用确定框。</p><p>Ubuntu 总是配置好了一个对话框，每当你要关机、重启或者注销时提示你。</p><p>这是一个保护措施，防止你本不打算这样做却错误关机或重启。</p><p>不是所有人都想每次关机的时候被询问。忙碌的小伙伴们可能就让自己的电脑那么醒着，因为他执行了关闭命令，却忘了确认那个该死的对话框。</p><p>这个教程将会指导你每一次关机的时候如何避免那个对话框。</p><p>当这个特性被激活，你将会收到下面的提示。</p><blockquote><p>Are you sure you want to close all programs and shutdown your computer?</p></blockquote><p>运行下面命令关掉它。</p><p>按下键盘上的 <strong>Ctrl – Alt – T</strong> 打开终端。然后敲击下面的命令</p><pre><code>gsettings set com.canonical.indicator.session suppress-logout-restart-shutdown true
</code></pre><p>就这么简单，你再也不会被该死的确认对话框骚扰了。</p><p>如果想恢复这个对话框，敲下面的命令就可以了</p><pre><code>gsettings set com.canonical.indicator.session suppress-logout-restart-shutdown false
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/shutdownubuntuconfirm.png" alt=""></p><p>干巴爹！</p><hr>`,19)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-turn-off-shutdown-restart-confirmation-in-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-turn-off-shutdown-restart-confirmation-in-ubuntu/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=n("译者：",-1)),e(u,{href:"https://github.com/ggaaooppeenngg"},{default:o(()=>[...t[2]||(t[2]=[n("ggaaooppeenngg",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),e(u,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),e(u,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const h=s(d,[["render",b]]);export{_ as __pageData,h as default};
